#include <metal_stdlib>
#include <MetalPerformancePrimitives/MetalPerformancePrimitives.h>
using namespace metal;
using namespace mpp::tensor_ops;

kernels.source:
constexpr int SM = 32, SN = 32, SK = 32;

const int M = int(dims[0]);
const int N = int(dims[1]);
const int K = int(dims[2]);
(void)M;

const int tgx = int(threadgroup_position_in_grid.x);
const int tgy = int(threadgroup_position_in_grid.y);
const int row = tgx * SM * 2;
const int col = tgy * SN * 2;

constexpr auto desc = matmul2d_descriptor(
    SM, SN, SK, false, true, true,
    matmul2d_descriptor::mode::multiply_accumulate);
matmul2d<desc, execution_simdgroup> op;

    auto ct_a0 = op.get_left_input_cooperative_tensor<int8_t, int8_t, int>();
auto ct_a1 = op.get_left_input_cooperative_tensor<int8_t, int8_t, int>();
auto ct_b0 = op.get_right_input_cooperative_tensor<int8_t, int8_t, int>();
auto ct_b1 = op.get_right_input_cooperative_tensor<int8_t, int8_t, int>();
auto ct_c00 = op.get_destination_cooperative_tensor<decltype(ct_a0), decltype(ct_b0), int>();
auto ct_c01 = op.get_destination_cooperative_tensor<decltype(ct_a0), decltype(ct_b1), int>();
auto ct_c10 = op.get_destination_cooperative_tensor<decltype(ct_a1), decltype(ct_b0), int>();
auto ct_c11 = op.get_destination_cooperative_tensor<decltype(ct_a1), decltype(ct_b1), int>();

    for (ushort i = 0; i < ct_c00.get_capacity(); ++i) ct_c00.set(i, 0);
for (ushort i = 0; i < ct_c01.get_capacity(); ++i) ct_c01.set(i, 0);
for (ushort i = 0; i < ct_c10.get_capacity(); ++i) ct_c10.set(i, 0);
for (ushort i = 0; i < ct_c11.get_capacity(); ++i) ct_c11.set(i, 0);

for (int k = 0; k < K; k += SK) {

  tensor<device int8_t, extents<int32_t, SK, SM>, tensor_inline> sA0(
      (device int8_t*)(A + (size_t)(row + 0 * SM) * K + k),
      extents<int32_t, SK, SM>(), array<int32_t, 2>{1, K});
  ct_a0.load(sA0);
  tensor<device int8_t, extents<int32_t, SK, SM>, tensor_inline> sA1(
      (device int8_t*)(A + (size_t)(row + 1 * SM) * K + k),
      extents<int32_t, SK, SM>(), array<int32_t, 2>{1, K});
  ct_a1.load(sA1);

  tensor<device int8_t, extents<int32_t, SK, SN>, tensor_inline> sB0(
      (device int8_t*)(B + (size_t)(col + 0 * SN) * K + k),
      extents<int32_t, SK, SN>(), array<int32_t, 2>{1, K});
  ct_b0.load(sB0);
  tensor<device int8_t, extents<int32_t, SK, SN>, tensor_inline> sB1(
      (device int8_t*)(B + (size_t)(col + 1 * SN) * K + k),
      extents<int32_t, SK, SN>(), array<int32_t, 2>{1, K});
  ct_b1.load(sB1);
        op.run(ct_a0, ct_b0, ct_c00);
  op.run(ct_a0, ct_b1, ct_c01);
  op.run(ct_a1, ct_b0, ct_c10);
  op.run(ct_a1, ct_b1, ct_c11);
}

for (ushort i = 0; i < ct_c00.get_capacity(); ++i) {
    auto mi = ct_c00.get_multidimensional_index(i);
    const int r = row + 0 * SM + mi[1];
    const int c = col + 0 * SN + mi[0];
    D[(size_t)r * N + c] = (half)((float)ct_c00[i] * a_scale[r] * w_scale[c]);
}
for (ushort i = 0; i < ct_c01.get_capacity(); ++i) {
    auto mi = ct_c01.get_multidimensional_index(i);
    const int r = row + 0 * SM + mi[1];
    const int c = col + 1 * SN + mi[0];
    D[(size_t)r * N + c] = (half)((float)ct_c01[i] * a_scale[r] * w_scale[c]);
}
for (ushort i = 0; i < ct_c10.get_capacity(); ++i) {
    auto mi = ct_c10.get_multidimensional_index(i);
    const int r = row + 1 * SM + mi[1];
    const int c = col + 0 * SN + mi[0];
    D[(size_t)r * N + c] = (half)((float)ct_c10[i] * a_scale[r] * w_scale[c]);
}
for (ushort i = 0; i < ct_c11.get_capacity(); ++i) {
    auto mi = ct_c11.get_multidimensional_index(i);
    const int r = row + 1 * SM + mi[1];
    const int c = col + 1 * SN + mi[0];
    D[(size_t)r * N + c] = (half)((float)ct_c11[i] * a_scale[r] * w_scale[c]);
}

constexpr int NT = 256;
const int K = int(dims[0]);
const uint row = threadgroup_position_in_grid.x;
const uint tid = thread_position_in_threadgroup.x;
const uint lane = tid % 32u;
const uint sg = tid / 32u;

const device half* xr = x + (size_t)row * K;
device int8_t* cr = codes + (size_t)row * K;

threadgroup float smax[NT / 32];

float m = 1e-8f;
for (int i = int(tid); i < K; i += NT) {
    m = max(m, fabs((float)xr[i]));
}
m = simd_max(m);
if (lane == 0) smax[sg] = m;
threadgroup_barrier(mem_flags::mem_threadgroup);
if (sg == 0) {
    float v = (lane < NT / 32) ? smax[lane] : 0.0f;
    v = simd_max(v);
    if (lane == 0) smax[0] = v;
}
threadgroup_barrier(mem_flags::mem_threadgroup);
const float amax = smax[0];
const float s = amax / 127.0f;
const float inv = 127.0f / amax;
if (tid == 0) scales[row] = s;

for (int i = int(tid); i < K; i += NT) {
    cr[i] = (int8_t)clamp(rint((float)xr[i] * inv), -127.0f, 127.0f);
}

constexpr int MMAX = 8, R = 2, SGS = 4;
const int M = int(dims[0]);
const int N = int(dims[1]);
const int K = int(dims[2]);
const int lane = int(thread_index_in_simdgroup);
const int n0 = (int(threadgroup_position_in_grid.x) * SGS
                + int(simdgroup_index_in_threadgroup)) * R;
if (n0 >= N) return;            // whole simdgroup: n0 is per simdgroup

float acc[MMAX][R];
for (int m = 0; m < MMAX; ++m) for (int r = 0; r < R; ++r) acc[m][r] = 0.0f;
for (int k = lane * 16; k < K; k += 512) {
  float4 w[R][4];
  for (int r = 0; r < R; ++r) {
    const device char4* wp = (const device char4*)(W + (size_t)(n0 + r) * K + k);
    for (int i = 0; i < 4; ++i) w[r][i] = float4(wp[i]);
  }
  for (int m = 0; m < M; ++m) {
    const device auto* xp = x + (size_t)m * K + k;
    for (int i = 0; i < 4; ++i) {
      const float4 xv = float4(float(xp[4 * i]), float(xp[4 * i + 1]),
                               float(xp[4 * i + 2]), float(xp[4 * i + 3]));
      for (int r = 0; r < R; ++r) acc[m][r] += dot(xv, w[r][i]);
    }
  }
}
for (int m = 0; m < M; ++m) {
  for (int r = 0; r < R; ++r) {
    const float t = simd_sum(acc[m][r]);
    if (lane == 0) D[(size_t)m * N + n0 + r] = static_cast<T>(t * ws[n0 + r]);
  }
}

constexpr int NT = 256;
const int K = int(dims[0]);
const int NG = K / 64;
const uint row = threadgroup_position_in_grid.x;
const uint tid = thread_position_in_threadgroup.x;
const uint lane = tid % 32u;
const uint sg = tid / 32u;
auto xr = x + (size_t)row * K;
device int8_t* cr = codes + (size_t)row * K;
threadgroup float smax[NT / 32];
threadgroup int half_sum[NT / 32];

float m = 1e-8f;
for (int i = int(tid); i < K; i += NT) m = max(m, fabs((float)xr[i]));
m = simd_max(m);
if (lane == 0) smax[sg] = m;
threadgroup_barrier(mem_flags::mem_threadgroup);
if (sg == 0) {
    float v = (lane < NT / 32) ? smax[lane] : 0.0f;
    v = simd_max(v);
    if (lane == 0) smax[0] = v;
}
threadgroup_barrier(mem_flags::mem_threadgroup);
const float amax = smax[0];
const float inv = 127.0f / amax;
if (tid == 0) scales[row] = amax / 127.0f;

// a 256-wide stripe is four 64-wide groups; simdgroups 2j and 2j+1 cover group j
for (int base = 0; base < K; base += NT) {
    const int i = base + int(tid);
    int c = 0;
    if (i < K) {
        c = int(clamp(rint((float)xr[i] * inv), -127.0f, 127.0f));
        cr[i] = (int8_t)c;
    }
    const int hs = simd_sum(c);
    if (lane == 0) half_sum[sg] = hs;
    threadgroup_barrier(mem_flags::mem_threadgroup);
    if (tid < 4) {
        const int g = base / 64 + int(tid);
        if (g < NG) rowsum[(size_t)row * NG + g] = half_sum[2 * tid] + half_sum[2 * tid + 1];
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
}

